export const useCommonMixin = () => {
    /** 封装请求方法 **/
    const ajaxPromise = (url, data, type, attribute = {}, isNeedClean=true, isLoad=false) => {
        if(Object.prototype.toString.call(data)==='[object Object]'){
            // 响应式提交的数据 可能会有数组原型上的两个自定义添加的方法 需要去掉
            delete data['indexOfElem']
            delete data['removeElem']
        }
        let param = cleanParams(data)
        if(!isNeedClean){
            param = data;
        }
        return new Promise((resolve, reject) => {
            let tempLoading = null
            if(isLoad===true){
                tempLoading = ElLoading.service({
                    lock: true,
                    text: '请求中loading',
                    background: 'rgba(0, 0, 0, 0.2)',
                });
            }
            let ajaxMain = {
                url: url,
                type: type || 'get',
                timeout: 180000,
                headers: {
                    'X-CSRF-TOKEN': $('meta[name="csrf-token"]').attr('content'),
                    "jwt-token": localStorage.getItem('jwt_token')
                },
                data: param,
                ...attribute,
                success: function (res) {
                    tempLoading?.close?.()
                    resolve(res)
                },
                error: function (err) {
                    tempLoading?.close?.()
                    reject(err)
                },
                complete: (XMLHttpRequest, status) => {
                    tempLoading?.close?.()
                    //请求完成后最终执行参数
                    if (status === 'timeout') {
                        //超时,status还有success,error等值的情况
                        layer.msg('请求超时!')
                    }
                }
            }
            $.ajax(ajaxMain)
        })
    }

/**
 * 网络请求参数，通过封装ajax，变成返回 Promise 的格式
 *
 * @param url 接口地址，必填
 * @param data 接口参数
 * @param method 请求方法，默认get
 * @param clearParamsFlag 是否自动清除掉空的参数，默认为true
 *
 * TODO 加入错误提示，判断statusCode 和 后端是否成功，自动显示错误，且返回reject,只有成功请求才返回resolve
 */
export function ajaxPromise({url, data, method='get',clearParamsFlag=true, attributes = {}}) {
    let param = data
    if(clearParamsFlag) {
        param = cleanParams(data)
    }
    return new Promise((resolve, reject) => {
        let ajaxMain = {
            url: url,
            type: method,
            timeout: 180000,
            headers: {
                'X-CSRF-TOKEN': $('meta[name="csrf-token"]').attr('content'),
                "inventory-token": localStorage.getItem('surfaceKey'),
                "jwt-token": localStorage.getItem('jwt_token')
            },
            data: param,
            ...attributes,
            success: function (res) {
                resolve(res)
            },
            error: function (err) {
                reject(err)
            },
            complete: (XMLHttpRequest, status) => {
                //请求完成后最终执行参数
                if (status === 'timeout') {
                    //超时,status还有success,error等值的情况
                    layer.msg('请求超时!')
                }
            }
        }
        $.ajax(ajaxMain)
    })
}

function cleanParams(obj){
    return Object.fromEntries(
        Object.entries(obj || {}).filter(([key, value]) => value !== null && value !== undefined && value !== '' && (typeof value !== 'string' || value.trim() !== ''))
    )
}

